const order = $input.item.json;

const lines = typeof order.order_lines === 'string'
  ? JSON.parse(order.order_lines)
  : order.order_lines;

if (!Array.isArray(lines) || lines.length === 0) {
  throw new Error('Order contains no lines');
}

if (!order.external_reference) {
  throw new Error('Missing external order reference');
}

const erpPayload = {
  external_reference: order.external_reference,
  shop_domain: order.shop_domain,
  shopify_order_id: order.shopify_order_id,
  order_number: order.order_number,
  currency: order.currency,
  total_amount: order.total_amount,
  customer: order.customer_data,
  lines: lines.map(line => ({
    sku: line.sku,
    quantity: line.quantity,
    unit_price: line.unit_price
  }))
};

return {
  json: {
    ...order,
    erp_payload: erpPayload
  }
};

const response = $input.item.json;
const order = $('Prepare ERP Payload').item.json;

const statusCode = Number(response.statusCode ?? 0);

let body = response.body ?? response;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}

if (!body || typeof body !== 'object') {
  body = {};
}

const result = body.result ?? null;
const erpOrderId = body.odoo_order_id ?? null;

let outcome = 'retryable_failure';
let retryable = true;
let errorCategory = 'erp_temporary_failure';
let errorMessage =
  response.error?.message ??
  response.message ??
  body.error ??
  `ERP request failed (HTTP ${statusCode})`;

if (
  statusCode >= 200 &&
  statusCode < 300 &&
  ['created', 'duplicate'].includes(result) &&
  typeof erpOrderId === 'string' &&
  erpOrderId.trim() !== ''
) {
  outcome = 'success';
  retryable = false;
  errorCategory = null;
  errorMessage = null;
} else if (
  ['conflict', 'invalid'].includes(result) ||
  [400, 409, 422].includes(statusCode)
) {
  outcome = 'permanent_failure';
  retryable = false;
  errorCategory = String(result ?? 'erp_validation');
  errorMessage = String(body.error ?? 'ERP rejected the order');
}

return {
  json: {
    job_id: order.job_id,
    lease_token: order.lease_token,
    outcome,
    retryable,
    erp_order_id: erpOrderId,
    error_category: errorCategory,
    error_message: String(errorMessage ?? ''),
    http_status: statusCode,
    erp_result: result
  }
};
